[StructLayout(LayoutKind.Sequential)]
internal struct SYSTEMTIME
{
    public ushort wYear;
    public ushort wMonth;
    public ushort wDayOfWeek;
    public ushort wDay;
    public ushort wHour;
    public ushort wMinute;
    public ushort wSecond;
    public ushort wMilliseconds;

    public static explicit operator SYSTEMTIME(DateTime dt) => new()
    {
        wYear = (ushort)dt.Year,
        wMonth = (ushort)dt.Month,
        wDayOfWeek = (ushort)dt.DayOfWeek,
        wDay = (ushort)dt.Day,
        wHour = (ushort)dt.Hour,
        wMinute = (ushort)dt.Minute,
        wSecond = (ushort)dt.Second,
        wMilliseconds = (ushort)dt.Millisecond
    };

    public static explicit operator DateTime(SYSTEMTIME st)
    {
        try
        {
            return new DateTime(st.wYear, st.wMonth, st.wDay, st.wHour, st.wMinute, st.wSecond, st.wMilliseconds);
        }
        catch
        {
            return DateTime.MinValue;
        }
    }
}

